async function refreshSaves(){try{const lives=await listLives();$('save-list').innerHTML=lives.length?lives.map(l=>{const c=calendar(l.day);return `<button class="save-slot" data-load="${esc(l.id)}"><span class="save-icon" style="background:${COATS[l.coat%6]}">⌂</span><span><strong>${esc(l.name)}的${SEASONS[c.season]}天</strong><small>第 ${c.year} 年 · ${SEASONS[c.season]} ${c.date} 日 · ${IDENTITIES[l.identity]?.name??'小镇居民'}</small></span><span class="slot-arrow">→</span></button>`;}).join(''):'<div class="empty-note">这里还没有留下日子。<br>给自己一个慢慢开始的机会吧。</div>';}catch(e){$('save-list').innerHTML='<div class="empty-note">本地存档暂时不可用。<br>仍可开始游玩，记得导出进度。</div>';$('storage-note').textContent=e.message;}}
