function updateHUD(){if(!state)return;const p=state.player,c=calendar(state.day);$('game-date').textContent=mobileLayout.matches?`${SEASONS[c.season]} ${c.date} 日`:`第 ${c.year} 年 · ${SEASONS[c.season]} ${c.date} 日`;$('game-weather').textContent=`${WEATHER[state.weather]} · ${mobileLayout.matches?'周':'星期'}${WEEKDAYS[c.weekday]}`;$('game-clock').textContent=clock(state.minute);$('season-icon').textContent=['♧','☼','❧','❄'][c.season];$('coin-count').textContent=p.coins.toLocaleString('zh-CN');$('player-caption').textContent=p.name+' · '+ageOf(state)+' 岁';$('location-name').textContent=building(p.inside)?.name??AREAS[p.area].name;$('location-note').textContent=paused?'时间暂停在这一刻。':state.weather==='rain'?'雨落在屋檐上，今天也不着急。':state.minute>=1140?'窗里的灯，正等着晚归的人。':'走一走，普通的日子也有回声。';for(const key of['energy','hunger','mood']){$(key+'-value').textContent=Math.round(p[key]);$(key+'-meter').style.width=p[key]+'%';}$('pause-game').textContent=paused?'▷':'Ⅱ';$('clock-status').textContent=paused?'点击继续':'时间流动中';$('clock-toggle').classList.toggle('clock-paused',paused);$('clock-toggle').setAttribute('aria-pressed',String(paused));$('clock-toggle').setAttribute('aria-label',paused?'继续小镇时间':'暂停小镇时间');$('pause-game').setAttribute('aria-label',paused?'继续时间':'暂停时间');$('sound-quick').setAttribute('aria-label',sound.enabled?'关闭游戏声音':'开启游戏声音');$('sound-quick').setAttribute('aria-pressed',String(sound.enabled));$('sound-quick').classList.toggle('muted',!sound.enabled);$('sound-quick').title=!sound.enabled?'声音已静音':sound.ready?'音乐与环境声正在播放':'点击后播放游戏声音';}
