function refreshEntities(){if(!state)return;entities=world.entities(state);const p=state.player;nearest=entities.filter(e=>Math.hypot(e.x-p.x,e.z-p.z)<(e.type==='npc'?3:2.35)).sort((a,b)=>Math.hypot(a.x-p.x,a.z-p.z)-Math.hypot(b.x-p.x,b.z-p.z))[0]??null;$('context-hint').hidden=!nearest||!!panel||dialogOpen||transitioning;$('touch-interact').disabled=!nearest;$('interact-label').textContent=!nearest?'靠近互动':nearest.type==='building'?'进入':nearest.type==='npc'?'交谈':nearest.kind==='exit'?'出门':nearest.type==='gate'?'前往':nearest.kind==='plot'?'照料':'互动';if(nearest)$('context-text').textContent=(nearest.type==='building'?'推门进入 · ':nearest.type==='gate'?'前往 · ':'')+getEntityName(nearest);}
function walkTo(x,z,entity=null){if(!state||transitioning)return;const p=state.player,target=nearestWalkable(p.area,x,z,p.inside);if(!target){toast('这里暂时走不过去，换一条路吧。');return;}path=findPath(p.area,[p.x,p.z],target,p.inside);pending=entity?{...entity,reroute:0}:null;mapView.pointer=target;world.highlight(entity??{x:target[0],z:target[1]});if(!path.length&&Math.hypot(p.x-target[0],p.z-target[1])>1.5){pending=null;toast('这条路还走不过去，可以试试从另一边绕行。');}else if(path.length&&paused){paused=false;updateHUD();}}
async function useEntity(e){if(!state||!e||transitioning)return;path=[];pending=null;world.highlight(e);if(e.type==='building'){await perform('enter',{id:e.id});return;}if(e.type==='npc'){openPanel('npc',{id:e.id});return;}if(e.type==='gate'){const g=GATES.find(g=>g.id===e.id);if(g)await goThrough(g);return;}if(e.type==='prop'){openPanel(e.kind==='board'?'journal':'prop',e);return;}if(e.type==='animal'){const result=act(state,'pet',{id:e.id});if(result.ok){world.active?.town?.interact(e.data);markDirty();updateHUD();sound.play(e.data.type==='cat'?'cat':e.data.type==='duck'?'duck':'pet');}toast(result.message);return;}
  if(e.type==='furniture'){if(e.kind==='exit')await perform('exit');else if(e.kind==='sleep')await perform('sleep');else if(e.kind==='mirror')openPanel('mirror');else if(e.kind==='diary')openPanel('room');else if(e.kind==='counter')openPanel('room');else if(['cook','bath','study','work','paint','rest'].includes(e.kind))await perform(e.kind);else if(e.kind==='treatment')await perform('heal');}}
async function goThrough(gate){if(!state||state.player.area!==gate.area||state.player.inside)return;advance(state,8);sound.play('enter');const p=state.player;p.area=gate.to;[p.x,p.z]=gate.spawn;markDirty();viewKey='';await switchView();toast('走进了'+AREAS[gate.to].name+'。');if(journey.length&&journey[0].id===gate.id)journey.shift();continueJourney();}
async function navigate(area,buildingId=null,npcId=null){if(!state)return;closePanel();if(state.player.inside)await perform('exit');destination={area,buildingId,npcId};journey=pathBetweenAreas(state.player.area,area);continueJourney();}
function continueJourney(){if(!state)return;if(journey.length){const g=journey[0];walkTo(g.x,g.z,{...g,type:'gate'});return;}if(!destination)return;const d=destination;destination=null;if(d.npcId){const n=state.npcs.find(n=>n.id===d.npcId);if(!n||n.transit){toast('TA 正在路上，过一会儿再看看邻里手记吧。');return;}if(n.area!==state.player.area){navigate(n.area,null,d.npcId);return;}if(n.inside){const b=building(n.inside);walkTo(...b.door,{...b,type:'building',x:b.door[0],z:b.door[1]});}else walkTo(n.x,n.z,{...n,type:'npc'});return;}if(d.buildingId){const b=building(d.buildingId);walkTo(...b.door,{...b,type:'building',x:b.door[0],z:b.door[1]});}else if(d.area==='farm')walkTo(-5,1);else walkTo(0,0);}
function attachWorldInput(canvas){let down=null;canvas.addEventListener('pointerdown',e=>{if(e.button===0)down={x:e.clientX,y:e.clientY};});canvas.addEventListener('pointerup',e=>{if(!down||e.button!==0)return;const from=down;down=null;if(Math.hypot(from.x-e.clientX,from.y-e.clientY)>8||phase!=='playing'||panel||dialogOpen||transitioning)return;const point=screenToGround(e.clientX,e.clientY);if(!point)return;refreshEntities();let chosen=null,best=Infinity;for(const entity of entities){const q=entityScreen(entity),d=Math.hypot(q.x-e.clientX,q.y-e.clientY);if(d<Math.max(19,(settings.mode==='2d'?mapView.scale:18)*1.1)&&d<best){chosen=entity;best=d;}}journey=[];destination=null;if(chosen){const distance=Math.hypot(chosen.x-state.player.x,chosen.z-state.player.z);if(distance<(chosen.type==='npc'?3:2.35))useEntity(chosen);else walkTo(chosen.x,chosen.z,chosen);}else walkTo(...point);});canvas.addEventListener('contextmenu',e=>e.preventDefault());}
