function screenToGround(x,y){if(settings.mode==='2d')return mapView.ground(x,y);if(!renderer)return null;pointer.set(x/sceneSize.width*2-1,-y/sceneSize.height*2+1);raycaster.setFromCamera(pointer,camera);const p=raycaster.ray.intersectPlane(groundPlane,new THREE.Vector3());return p?[p.x,p.z]:null;}
