function updateLabels(){if(!state||phase!=='playing')return;const nearby=entities.filter(e=>e.type==='npc'&&Math.hypot(e.x-state.player.x,e.z-state.player.z)<(mobileLayout.matches?7:12)).sort((a,b)=>Math.hypot(a.x-state.player.x,a.z-state.player.z)-Math.hypot(b.x-state.player.x,b.z-state.player.z));const placed=[];$('npc-labels').replaceChildren();for(const n of nearby){const pos=entityScreen(n,2),name=getEntityName(n),width=name.length*10+18,r={left:pos.x-width/2,right:pos.x+width/2,top:pos.y-22,bottom:pos.y};if(r.left<sceneRect.left||r.top<sceneRect.top||r.right>sceneRect.right||r.bottom>sceneRect.bottom)continue;const overlaps=q=>r.left<q.right+3&&r.right>q.left-3&&r.top<q.bottom+3&&r.bottom>q.top-3;if(labelBlockers.some(overlaps)||placed.some(overlaps))continue;placed.push(r);const label=document.createElement('span');label.className='npc-label';label.textContent=name;label.style.left=pos.x+'px';label.style.top=pos.y+'px';$('npc-labels').appendChild(label);if(placed.length>=(mobileLayout.matches?3:8))break;}}

function movement(dt){const p=state.player;let dx=(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0),dz=(keys.has('KeyS')||keys.has('ArrowDown')?1:0)-(keys.has('KeyW')||keys.has('ArrowUp')?1:0);let walked=0;const usingStick=Math.hypot(stick.x,stick.z)>.01;if(usingStick){dx=stick.x;dz=stick.z;}
  if(dx||dz){path=[];pending=null;journey=[];destination=null;mapView.pointer=null;const len=Math.hypot(dx,dz);dx/=len;dz/=len;const strength=usingStick?Math.min(1,len):1;if(settings.mode==='3d'){const angle=Math.atan2(cameraOffset.x,cameraOffset.z),xx=dx*Math.cos(angle)+dz*Math.sin(angle),zz=-dx*Math.sin(angle)+dz*Math.cos(angle);dx=xx;dz=zz;}const distance=dt*(p.energy<12?2:3.1)*strength,nx=p.x+dx*distance,nz=p.z+dz*distance,oldx=p.x,oldz=p.z;if(walkable(p.area,nx,nz,p.inside)){p.x=nx;p.z=nz;}else{if(walkable(p.area,nx,p.z,p.inside))p.x=nx;if(walkable(p.area,p.x,nz,p.inside))p.z=nz;}p.facing=Math.atan2(dx,dz);walked=Math.hypot(p.x-oldx,p.z-oldz);}
  else if(path.length)walked=moveAlong(p,path,dt*(p.energy<12?2:3.1));
  if(walked){sound.footsteps(walked,p.inside?'wood':p.area==='center'||Math.abs(p.x)<2||Math.abs(p.z)<2?'path':'grass');p.steps+=walked;p.energy=Math.max(0,p.energy-walked*.012);markDirty();}
  if(pending){pending.reroute+=dt;const liveState=pending.type==='npc'?state.npcs.find(n=>n.id===pending.id):null,live=liveState?{...liveState,...npcPose(state,liveState)}:null;if(live&&live.area===p.area&&live.inside===p.inside){pending.x=live.x;pending.z=live.z;}const distance=Math.hypot(p.x-pending.x,p.z-pending.z);if(distance<(pending.type==='npc'?2.7:1.8)){const e=pending;pending=null;path=[];useEntity(e);}else if(!path.length&&pending.reroute>1){if(live&&!live.transit&&!live.inside){const e={...pending};walkTo(live.x,live.z,e);}else{pending=null;mapView.pointer=null;}}}
  if(!path.length&&!pending)mapView.pointer=null;return walked>.001;
}
