function frame(now){requestAnimationFrame(frame);const raw=(now-lastFrame)/1000;lastFrame=now;if(document.hidden)return;const dt=Math.min(raw,.25);frameCount++;if(now-fpsStart>1000){fps=Math.round(frameCount*1000/(now-fpsStart));frameCount=0;fpsStart=now;}
  const blend=reducedMotion?1:Math.min(1,raw*12);if(Math.abs(sceneAnchor.x-sceneAnchorTarget.x)+Math.abs(sceneAnchor.y-sceneAnchorTarget.y)>.1){sceneAnchor.x+=(sceneAnchorTarget.x-sceneAnchor.x)*blend;sceneAnchor.y+=(sceneAnchorTarget.y-sceneAnchor.y)*blend;projectScene();}
  const focus=sceneFocus();mapView.anchor=sceneAnchor;mapView.focus=focus;mapView.highlight=panel==='prop'?panelData:null;
  let moving=false;const blocked=phase!=='playing'||paused||panel||dialogOpen||transitioning||conflict;
  const steps=runtimeClock.sample(now,!!state&&!blocked);
  if(!blocked||phase!=='playing')visualTime+=Math.min(raw,2)*1000;
  if(state&&!blocked){let movementTime=Math.min(raw,2);while(movementTime>1e-6){const step=Math.min(.05,movementTime);moving=movement(step)||moving;movementTime-=step;if(panel||dialogOpen||transitioning)break;}
    for(let step=0;step<steps&&!panel&&!dialogOpen&&!transitioning;step++){const prevDay=state.day;advance(state,.15);markDirty();if(state.day!==prevDay){closePanel();viewKey='';switchView().then(()=>{persist(true);showMorning();});runtimeClock.reset(now);break;}}if(panel||dialogOpen||transitioning)runtimeClock.reset(now);autosaveAccum+=steps*.1;if(autosaveAccum>20){autosaveAccum=0;persist();}}
  else if(phase!=='playing'&&!transitioning)advance(preview,Math.min(raw,2)*1.5);
  mapView.playerMoving=moving;
  const s=state??preview;sound.update(s,{ducked:!!panel||dialogOpen||phase!=='playing'});if(settings.mode==='2d')mapView.render(s,visualTime,phase!=='playing');else if(renderer&&!transitioning){if(viewKey!==(s.player.inside?'room:'+s.player.inside:s.player.area)+'|3d')switchView();else{updateAvatar();world.update(s,phase==='playing'&&!blocked?dt:phase==='title'?dt*.4:0,camera);const p=s.player;if(playerAvatar){playerAvatar.root.visible=phase==='playing';playerAvatar.root.position.set(p.x,world.height(p.area,p.x,p.z,p.inside),p.z);playerAvatar.root.rotation.y=p.facing;playerAvatar.model.rotation.z=(p.health<40?.05:0);playerAvatar.animate(blocked?0:dt,moving);}
      const target=new THREE.Vector3(focus.x,1,focus.z);if(controls){const delta=target.clone().sub(controls.target).multiplyScalar(reducedMotion?1:Math.min(1,dt*7));camera.position.add(delta);controls.target.add(delta);controls.update();}sun.position.set(target.x-22,42,target.z+27);sun.target.position.copy(target);const daylight=Math.max(.12,Math.sin((s.minute/60-6)/24*Math.PI*2));hemi.intensity=.65+daylight*.95;sun.intensity=.2+daylight*2.25;sun.color.set(s.minute>1000?'#ffd8b3':'#fff9ed');const bg=new THREE.Color(s.minute<350||s.minute>1200?'#314f6b':s.weather==='rain'?'#a3c7d2':'#bee4ef');scene.background.lerp(bg,.05);scene.fog.color.copy(scene.background);if(weatherPoints){weatherPoints.visible=!p.inside&&(s.weather==='rain'||s.weather==='snow');if(weatherPoints.visible){const snow=s.weather==='snow';weatherPoints.material.size=snow?.09:.045;for(let i=0;i<weatherPositions.length/3;i++){weatherPositions[i*3]=p.x+Math.sin(i*72.34)*22+(snow?Math.sin(now*.0005+i)*.5:0);weatherPositions[i*3+1]=(i*.73-now*(snow?.0007:.012)+100000)%24;weatherPositions[i*3+2]=p.z+Math.cos(i*43.71)*22;}weatherPoints.geometry.attributes.position.needsUpdate=true;}}renderer.render(scene,camera);}}
  uiAccum+=dt;entityAccum+=dt;if(phase==='playing'&&entityAccum>.2){entityAccum=0;refreshEntities();}if(phase==='playing'&&uiAccum>.2){uiAccum=0;updateHUD();updateLabels();}
}
