const draft={gender:'女',skin:0,hair:0,coat:0,hairstyle:0,accessory:0};
function drawPortrait(){const canvas=$('portrait-canvas'),c=canvas.getContext('2d');if(!c)return;c.clearRect(0,0,320,380);c.save();c.translate(160,200);const shape=(x,y,w,h,r,color)=>{c.fillStyle=color;c.beginPath();c.roundRect(x-w/2,y-h/2,w,h,r);c.fill();},oval=(x,y,rx,ry,color)=>{c.fillStyle=color;c.beginPath();c.ellipse(x,y,rx,ry,0,0,7);c.fill();};oval(0,136,61,12,'#a3b49435');shape(-20,110,23,48,10,'#7c8778');shape(20,110,23,48,10,'#7c8778');oval(-22,135,17,10,'#665d51');oval(22,135,17,10,'#665d51');shape(0,65,83,92,32,COATS[draft.coat]);shape(-47,66,19,64,10,COATS[draft.coat]);shape(47,66,19,64,10,COATS[draft.coat]);oval(-48,100,10,11,SKINS[draft.skin]);oval(48,100,10,11,SKINS[draft.skin]);if(draft.hairstyle===1)shape(0,-3,116,112,40,HAIRS[draft.hair]);oval(0,-18,55,60,SKINS[draft.skin]);oval(0,-42,57,38,HAIRS[draft.hair]);oval(0,-11,50,47,SKINS[draft.skin]);oval(-27,-47,27,13,HAIRS[draft.hair]);oval(6,-51,30,13,HAIRS[draft.hair]);oval(-53,-10,8,12,SKINS[draft.skin]);oval(53,-10,8,12,SKINS[draft.skin]);oval(-18,-12,3.2,4,'#504b42');oval(18,-12,3.2,4,'#504b42');oval(-31,3,8,4,'#d99f97');oval(31,3,8,4,'#d99f97');c.strokeStyle='#a78168';c.lineWidth=1.5;c.beginPath();c.arc(0,6,8,.3,2.84);c.stroke();if(draft.hairstyle===2)oval(0,-85,22,20,HAIRS[draft.hair]);if(draft.accessory===1){c.strokeStyle='#756b59';c.lineWidth=3;for(const x of[-19,19]){c.beginPath();c.arc(x,-13,13,0,7);c.stroke();}c.beginPath();c.moveTo(-6,-13);c.lineTo(6,-13);c.stroke();}if(draft.accessory===2){oval(0,-64,76,10,'#e6d3a1');shape(0,-82,86,39,14,'#e6d3a1');shape(0,-66,88,9,0,COATS[draft.coat]);}for(let i=0;i<3;i++)oval(0,47+i*17,3,3,'#f6ebd1');shape(23,63,23,19,3,'#eee0bc');c.restore();}
