$('expand-panel').onclick=()=>setPanelExpanded(!panelExpanded);$('close-panel').onclick=closePanel;$('panel-shade').onclick=closePanel;$('title-settings').onclick=()=>openPanel('settings');$('game-settings').onclick=()=>openPanel('settings');$('home-menu').onclick=()=>openPanel('settings');$('profile-open').onclick=()=>openPanel('profile');$('pause-game').onclick=togglePause;$('clock-toggle').onclick=togglePause;$('dismiss-tip').onclick=()=>{$('first-tip').hidden=true;state.flags.dismissedTip=true;markDirty();};$('touch-interact').onclick=()=>{refreshEntities();useEntity(nearest);};
