$('panel-content').onclick=async event=>{const button=event.target.closest('button');if(!button||button.disabled)return;const d=button.dataset;if(d.act){const data={...d};delete data.act;if(data.all)data.all=true;await perform(d.act,data);}else if(d.travel)navigate(d.travel);else if(d.destination){const b=building(d.destination);navigate(b.area,b.id);}else if(d.person)openPanel('person',{id:d.person});else if(d.findnpc){const npc=state.npcs.find(n=>n.id===d.findnpc);navigate(npc.area,null,npc.id);}else if('mirror'in d)openPanel('mirror');else if(d.appearance){state.player[d.appearance]=Number(d.value);markDirty();updateAvatar();renderCurrentPanel();}else if('save'in d){if(await persist(true))toast('这一刻已经收好了。');}else if('export'in d)downloadSave();else if('title'in d)backToTitle();else if('import'in d)$('import-file').click();else if('backups'in d){try{openPanel('backups',{entries:await listBackups(state.id)});}catch(e){toast(e.message);}}else if(d.restore){showDialog('回到这一页日记？','会恢复到这份备份的时间与状态，当前进度也会保留为备份。',[{text:'再想想'},{text:'恢复这份日子',primary:true,run:async()=>{try{if(saving)await saving;await startLife(await restoreBackup(state.id,d.restore,state));toast('已恢复这份日子。');}catch(e){toast(e.message);}}}]);}else if('sound'in d){await toggleSound();renderCurrentPanel();}else if('pause'in d){togglePause();}};
$('panel-content').onchange=event=>{const volume=event.target.dataset.volume;if(volume){sound.setVolume(volume,Number(event.target.value)/100);return;}const setting=event.target.dataset.setting;if(setting==='mode'){setMode(event.target.value);renderCurrentPanel();}else if(setting==='quality'){settings.quality=event.target.value;applyQuality();storeSettings();renderCurrentPanel();}};
$('import-life').onclick=()=>$('import-file').click();$('import-file').onchange=async event=>{const file=event.target.files?.[0];if(!file)return;try{if(file.size>2_000_000)throw new Error('存档文件过大，请选择小镇导出的 JSON。');if(state&&!await persist(true))throw new Error('先导出当前人生，再导入另一份存档。');const id=await importLife(await file.text());await refreshSaves();closePanel();toast('已导入为一段独立人生。');showDialog('把这段日子接着过？','存档已作为新副本导入，原来的人生仍然保留。',[{text:'留在当前页面'},{text:'进入这段人生',primary:true,run:async()=>startLife(await loadLife(id))}]);}catch(e){toast(e.message);}event.target.value='';};
document.addEventListener('keydown',event=>{if(event.key==='Tab'&&(dialogOpen||panel)){const surface=$(dialogOpen?'dialog-shade':'panel'),focusable=[...surface.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),a[href]')].filter(e=>e.getClientRects().length);if(focusable.length){const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&(document.activeElement===first||!surface.contains(document.activeElement))){event.preventDefault();last.focus();}else if(!event.shiftKey&&(document.activeElement===last||!surface.contains(document.activeElement))){event.preventDefault();first.focus();}}return;}if(['INPUT','SELECT','TEXTAREA'].includes(event.target.tagName))return;if(event.key==='Escape'){if(dialogOpen)closeDialog();else closePanel();keys.clear();return;}if(phase!=='playing'||dialogOpen)return;const key=event.code;if(['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(key)){if(!panel){event.preventDefault();keys.add(key);}return;}if(event.repeat)return;if(key==='KeyE'&&!panel){refreshEntities();useEntity(nearest);}else if(key==='Space'&&!panel){event.preventDefault();togglePause();}else{const kind={KeyB:'bag',KeyM:'map',KeyR:'people',KeyJ:'journal'}[key];if(kind)panel===kind?closePanel():openPanel(kind);}});
document.addEventListener('keyup',e=>keys.delete(e.code));addEventListener('blur',()=>{keys.clear();joystick.reset();});document.addEventListener('visibilitychange',()=>{lastFrame=performance.now();runtimeClock.reset(lastFrame);tickAccum=0;keys.clear();joystick.reset();if(document.hidden)persist();sound.setHidden(document.hidden);});
addEventListener('pagehide',()=>{persist();});
function togglePause(){if(phase!=='playing')return;paused=!paused;runtimeClock.reset(performance.now());updateHUD();if(panel)renderCurrentPanel();toast(paused?'小镇时间已暂停，点上方时钟继续。':'小镇时间继续流动了。');}
async function toggleSound(){await sound.toggle();settings.sound=sound.enabled;updateHUD();}
document.addEventListener('pointerdown',()=>{sound.unlock().then(()=>{if(state)updateHUD();});},{passive:true});
document.addEventListener('pointerup',event=>{if(event.target.closest('button')&&!event.target.closest('#touch-interact'))sound.play('ui');},{passive:true});
document.addEventListener('keydown',()=>{sound.unlock();},{passive:true});
$('panel-content').addEventListener('input',event=>{const key=event.target.dataset.volume;if(key){sound.setVolume(key,Number(event.target.value)/100);const label=$('volume-'+key);if(label)label.textContent=event.target.value+'%';}});

refreshSaves();setMode(settings.mode,false);
